'use strict';
const $=s=>document.querySelector(s),app=$('#app');
const assets='../../prototype/assets/';
const performers=[
 {name:'GAIA',file:'gaia.png',accent:'#5bd8ed',en:'An ocean of attention.',zh:'將感知，交給海洋。',atmosphere:'ocean'},
 {name:'PANDEMIC',file:'pandemic.png',accent:'#c0aa91',en:'A quieter kind of presence.',zh:'在靜謐中，感受存在。',atmosphere:'mineral'},
 {name:'RE-BIRTH',file:'rebirth.png',accent:'#e0b0c8',en:'A moment of becoming.',zh:'與蛻變的此刻相遇。',atmosphere:'petal'},
 {name:'WHITE-GUARDIAN',file:'guardian.png',accent:'#c5e9fa',en:'Stillness, held in light.',zh:'在光中，安放寧靜。',atmosphere:'ice'},
 {name:'CONSCIENCE',file:'conscience.png',accent:'#ff956a',en:'An ember of awareness.',zh:'感知，如餘燼微亮。',atmosphere:'ember'},
 {name:'SANCTUARY',file:'sanctuary.png',accent:'#f1c57a',en:'A space to return to.',zh:'回到，心中的安所。',atmosphere:'amber'}
];
const families=[['gallery','Color Release / gallery'],['home','Home'],['privacy','Privacy'],['tutorial','Tutorial'],['attract','Attract'],['focus','Focus'],['activation','Activation'],['portrait','Living Portrait'],['release','Release'],['postvideo','PostVideo'],['chooser','Assistant chooser'],['ai','Assistant conversation'],['settings','Settings'],['closing','Closing'],['souvenir','Souvenir'],['calibration','Conditional calibration'],['components','Components / recovery']];
$('#family').innerHTML=families.map(([id,n])=>`<option value="${id}">${n}</option>`).join('');
const state={view:'gallery',locale:'en',layout:'arc',target:-1,performer:0,gesture:'off',gestureTarget:-1,phase:'prepare',overlay:null,minimized:null,tutorial:0,error:false};
let sceneAnimations=[],routeGeneration=0,panelAnimation=null,panelGeneration=0,opener=null,reviewTimers=[],panelReturn=null;
const T=(en,zh)=>state.locale==='zh'?zh:en;
const P=()=>performers[state.performer];
const protectedState=()=>['activation','portrait'].includes(state.view);
const reduce=()=>$('#reduced').checked||matchMedia('(prefers-reduced-motion: reduce)').matches;
const art=(i,cls='')=>`<img data-art="${i}" class="${cls}" src="${assets+performers[i].file}" alt="${performers[i].name} · ${T('existing performer artwork','既有表演者作品')}" draggable="false">`;
const button=(a,en,zh,cls='primary',disabled=false)=>`<button class="${cls}" data-action="${a}"${disabled?' disabled':''}>${T(en,zh)}</button>`;
const log=(en,zh)=>{$('#event-log').textContent=T(en,zh);};
function header(){return `<header class="app-header"><div><p class="wordmark">AWAKENING CELEBRATIONS</p><p class="subtitle">${T('A LIVING GALLERY','感知流動的藝廊')}</p></div><button data-action="locale">${state.locale==='en'?'English / 繁體中文':'繁體中文 / English'}</button></header>`;}
function shell(){if(protectedState())return `<nav class="dock" aria-label="${T('Cinematic navigation','沉浸體驗導覽')}"><p>${T('Settings & AI after this moment','此段落結束後可開啟設定與 AI')}</p>${button('privacy','Privacy','隱私','quiet')}${button('safe-exit','Exit options','離開選項','quiet')}</nav>`;return `<nav class="dock" aria-label="${T('Global navigation','全域導覽')}">${['settings','ai','help','privacy'].map((id,i)=>`<button id="shell-${id}" data-action="${id}" aria-expanded="false">${[T('Settings','設定'),T('Ask AI','詢問 AI'),T('Help','說明'),T('Privacy','隱私')][i]}</button>`).join('')}<span class="camera-status">${T('Camera off','相機已關閉')}</span></nav>`;}
function gallery(){return '<div class="environment-light" aria-hidden="true"></div>'+header()+`<div class="view-title"><div><p class="eyebrow">${T('COLOR RELEASE / SIX PRESENCES','色彩釋放／六種存在')}</p><h1 class="display">${T('Find a presence.<br>Begin an awakening.','與存在相遇。<br>讓感知甦醒。')}</h1></div><div class="gallery-guidance"><p class="instruction">${T('Point to explore. Make a fist to confirm.<br>Or click a portrait. Keys 1–6 also choose.','指向以探索，握拳以確認。<br>也可點擊作品，或按 1–6 選擇。')}</p><p class="theme-state" aria-live="polite"></p></div></div><section class="gallery arc" aria-label="${T('Six performer gallery','六位表演者藝廊')}">${performers.map((p,i)=>`<button class="presence${state.target===i?' targeted':''}" style="--performer:${p.accent};--i:${i}" data-performer="${i}" data-region="PER-00${i+1} · stable region" aria-label="${p.name} — ${T('choose performer','選擇表演者')}"><span class="art-window"><span class="spatial-surface">${art(i,'portrait')}<span class="portrait-rim"></span><span class="portrait-reflection"></span></span></span><span class="art-caption"><span>${p.name}</span><small>0${i+1}</small></span></button>`).join('')}</section><section class="identification" aria-live="polite"><span class="identity-index">${state.target<0?'01—06':'0'+(state.target+1)}</span><div class="identity"><h2 id="identity-name">${state.target<0?T('Six artistic presences','六種藝術存在'):performers[state.target].name}</h2><p id="identity-copy">${state.target<0?T('Explore at your own pace. No choice has been made.','以自己的步調探索，尚未做出選擇。'):T(performers[state.target].en,performers[state.target].zh)}</p></div><button class="primary" data-action="confirm" ${state.target<0?'disabled':''}>${T('Enter this chapter','進入此篇章')}</button></section><div class="tracking" data-status="${state.gesture}">${trackingCopy()}</div>`;}
function trackingCopy(){const map={off:['Camera off · pointer & keyboard available','相機已關閉・可使用滑鼠與鍵盤'],ready:['Gesture ready · review illustration','手勢就緒・檢視示意'],target:['Target acquired · fist to confirm','已鎖定目標・握拳確認'],lost:['Tracking lost. Point again to reacquire.','失去追蹤，請重新指向目標。'],recovered:['Tracking recovered. Point to choose a new target.','追蹤已恢復，請重新指向目標。']};return T(...(map[state.gesture]||map.off));}
function chapter(){const v=state.view,ph=v==='portrait'?state.phase:v;const title={focus:T('Focus','凝視'),activation:T('Activation','啟動'),prepare:T('Preparing Living Portrait','正在準備流動畫像'),playing:T('Living Portrait','流動畫像'),release:T('Release','釋放')}[ph];let actions='';if(v==='focus')actions=button('activate','Begin awakening','開始甦醒')+`<p>${T('Show both open palms, or use this action.','張開雙手，或使用此操作。')}</p>`;if(v==='activation')actions=`<p class="status-plate">${T('A three-second visual passage.','三秒的視覺過渡。')}</p>`;if(ph==='prepare')actions=`<p class="status-plate">${T('Preparing… Artwork remains until a real first frame.','準備中…第一個實際影格出現前，保留原作品。')}</p>`;if(v==='release')actions=button('postvideo','Reflect on this moment','回望此刻')+button('gallery','Return to the gallery','返回藝廊','secondary');return art(state.performer,'chapter-art'+(v==='activation'?' activation-art':''))+`<div class="chapter-scrim"></div>${ph==='playing'?'':header()}<section class="chapter-copy"><p class="eyebrow">${title} / PER-00${state.performer+1}</p><h1 class="display">${P().name}</h1>${v==='focus'||v==='release'?`<p>${T(P().en,P().zh)}</p>`:''}</section><div class="chapter-actions">${actions}</div>`;}
function standard(view){let title,copy,actions,fine='';if(view==='home'){title=T('A world, awakened<br>through you.','讓世界，<br>因你而甦醒。');copy=T('Six performers. One shared exhibition. Take a moment, then follow your curiosity.','六位表演者，一場共同的展演。稍作停留，循著好奇心探索。');actions=button('privacy-page','Review & begin','閱讀並開始');fine=T('Your camera remains off. Camera permission is session-only.','相機保持關閉，相機同意僅限本次體驗。');}if(view==='attract'){title=T('There is room<br>for your presence.','此處，<br>為你留有空間。');copy=T('A quiet invitation to begin. Gesture interaction is available only after consent; pointer and keyboard alternatives remain visible.','邀你從容開始。手勢互動須先取得同意，並保留清楚的滑鼠與鍵盤操作提示。');actions=button('gallery','Explore the six presences','探索六種存在');fine=T('Design preview: no wave, clap or camera detector is running.','設計預覽：未啟動揮手、拍手或相機偵測。');}if(view==='closing'){title=T('Carry the feeling.<br>Leave room for more.','帶著感受離開。<br>為下一次相遇留白。');copy=T('Your experience can end here, or you can return to the gallery. A takeaway remains optional.','你可在此結束，也可返回藝廊。紀念留存為選用體驗。');actions=button('gallery','Return to the gallery','返回藝廊')+button('souvenir','Optional takeaway','選用紀念留存','secondary');fine=T('Ending/reset functionality remains deferred.','結束與重設功能仍暫緩實作。');}if(view==='souvenir'){title=T('A moment<br>to take with you.','將此刻，<br>留在身邊。');copy=T('A useful takeaway should extend the experience. Its content, destination and privacy policy require approval.','有意義的紀念內容應延續體驗。內容、目的地與隱私政策仍待核准。');actions=button('closing','Done','完成')+button('delivery','Delivery unavailable','留存服務未提供','secondary',true);fine=T('No delivery service or QR code is present.','此處未提供留存服務或 QR 碼。');}return header()+`<section class="standard"><div class="standard-copy"><p class="eyebrow">${view==='home'?'VER.KA':T('AWAKENING CELEBRATIONS','甦醒慶典')}</p><h1 class="display">${title}</h1><p>${copy}</p>${view==='souvenir'?`<div class="no-code">${T('Delivery unavailable · no QR code','留存服務未提供・沒有 QR 碼')}</div>`:''}<div class="actions">${actions}</div><p class="fine">${fine}</p></div>${art(view==='home'?5:state.performer,'standard-art')}</section>`;}
function reading(view){let title,body,actions;if(view==='privacy'){title=T('Your presence.<br>Your choice.','你的參與。<br>由你選擇。');body=`<span class="status-tag">${T('Camera off','相機已關閉')}</span><h2>${T('Before gesture interaction','開始手勢互動之前')}</h2><p>${T('Camera consent is a session choice. Preview visibility and capture permission are separate. No permission is granted by this design preview.','相機同意為本次體驗的選擇。預覽是否顯示與擷取權限分開處理。此設計預覽不會授予任何權限。')}</p><p>${T('Final camera and assistant data notices must describe the actual implementation. The consent-free entry policy is still awaiting approval.','最終相機與助理資料告知須符合實際實作。未同意相機時的完整參與流程仍待核准。')}</p>`;actions=button('tutorial','Preview next layout','預覽下一個版面')+button('home','Return Home','返回首頁','secondary');}if(view==='tutorial'){title=T('Move with ease.','從容，開始互動。');const steps=[['Point to explore. Make a fist to confirm.','指向以探索，握拳以確認。'],['Show both open palms to begin the portrait.','張開雙手，開始流動畫像。'],['Hold one open palm to request Back.','張開單手並保持，以請求返回。']];body=`<span class="status-tag">${T('Interaction guide','操作說明')} 0${state.tutorial+1} / 03</span><h2>${T(...steps[state.tutorial])}</h2><p>${T('Use the pointer, Tab, Enter/Space and the supported number keys as alternatives. Readiness and tracking loss are explained with text as well as light.','也可使用滑鼠、Tab、Enter／Space，以及支援的數字鍵。就緒與追蹤遺失狀態，會同時以文字與光線呈現。')}</p><div class="steps">${steps.map((_,i)=>`<span class="${i===state.tutorial?'active':''}">0${i+1}</span>`).join(' / ')}</div>`;actions=button('tutorial-next',state.tutorial===2?'Explore the gallery':'Next',state.tutorial===2?'探索藝廊':'下一步')+button('gallery','Skip guide','略過說明','secondary');}if(view==='calibration'){title=T('Alignment,<br>only if needed.','僅在需要時，<br>調整對位。');body=`<span class="status-tag">${T('Conditional feature','條件式功能')}</span><h2>${T('Keep the experience comfortable','讓操作維持舒適')}</h2><p>${T('Explain → check device and consent → acquire a stable target → evaluate → retry or cancel. Include this only if measured targeting evidence justifies a real calibration algorithm.','說明 → 檢查裝置與同意 → 取得穩定目標 → 評估 → 重試或取消。僅在實際定位證據支持校正需求與演算法時，才納入此功能。')}</p><p>${T('No target acquisition or successful calibration is simulated.','此處不會模擬目標取得或校正成功。')}</p>`;actions=button('calibrate','Calibration unavailable','校正目前無法使用','secondary',true)+button('gallery','Return to the gallery','返回藝廊');}return header()+`<section class="reading-layout"><h1 class="display">${title}</h1><div class="reading-surface">${body}<div class="actions">${actions}</div></div></section>`;}
function chooser(){return header()+`<section class="reading-layout"><div><p class="eyebrow">${T('A DIFFERENT PERSPECTIVE','換個角度，延續感知')}</p><h1 class="display">${T('Continue the<br>conversation.','讓對話，<br>繼續流動。')}</h1></div><div class="reading-surface"><h2>${T('Choose a perspective','選擇對話主題')}</h2><p>${T('Assistant context is separate from your selected performer.','助理對話主題與已選表演者分開保存。')}</p><div class="chooser">${performers.map((p,i)=>`<button data-assistant="${i}">${art(i)}<span>${p.name}</span></button>`).join('')}</div></div></section>`;}
function postvideo(){return header()+`<section class="standard"><div class="standard-copy"><p class="eyebrow">${P().name} / ${T('REFLECTION','回望')}</p><h1 class="display">${T('What stayed<br>with you?','哪份感受，<br>留在心中？')}</h1><p>${T('Continue with a question, return to the gallery, or close this chapter.','提出問題、返回藝廊，或在此結束這個篇章。')}</p><div class="actions">${button('ai','Ask about this presence','詢問此刻的存在')}${button('closing','Close this chapter','結束此篇章','secondary')}</div><p class="fine">${T('Assistant layout specimen; no message is sent.','助理版面示例，不會傳送訊息。')}</p></div>${art(state.performer,'standard-art')}</section>`;}
function components(){return header()+`<section class="specimen"><div class="component-grid"><article><h3>${T('One action language','一致的操作語言')}</h3>${button('gallery','Return to gallery','返回藝廊')}<p>${T('Hover → target. Activation → confirm. A focus ring stays distinct from performer light.','停留以指向，啟用以確認。焦點框與表演者光線清楚區別。')}</p>${button('deferred','Unavailable','目前無法使用','secondary',true)}</article><article><h3>${T('Readable glass','易讀的玻璃介面')}</h3><p>${T('Tinted chrome, floating identification, opaque reading regions. Refraction never distorts text or targets.','染色導覽、浮動識別面板、不透明閱讀區。折射不扭曲文字或互動目標。')}</p></article><article><h3>${T('Recovery','復原')}</h3><div class="inline-error">${T('Media unavailable. Keep the artwork and use the configured recovery route.','媒體目前無法使用，保留作品並採用設定的復原流程。')}</div><p>${T('Do not display a false completion.','不可顯示不實的播放完成狀態。')}</p></article><article><h3>${T('Deferred preferences','暫緩實作的偏好')}</h3><p>${T('Sound, accessibility and session reset retain designed unavailable states. Review controls do not apply product settings.','聲音、無障礙與體驗重設，皆保留已設計的無法使用狀態。檢視控制項不會套用產品設定。')}</p></article><article><h3>${T('Tracking recovery','追蹤復原')}</h3><p>${T('Tracking lost → clear gesture acquisition → ready → point again → fist. A new target is required.','失去追蹤 → 清除手勢目標 → 就緒 → 重新指向 → 握拳。必須重新取得目標。')}</p></article><article><h3>${T('Assistant unavailable','助理目前無法使用')}</h3><div class="inline-error">${T('No assistant connection is made in this preview.','此預覽不會連線至助理服務。')}</div></article></div></section>`;}
function cancelScene(){routeGeneration++;sceneAnimations.forEach(a=>a.cancel());sceneAnimations=[];}
function animateNode(node,frames,options){if(!node)return;if(reduce())frames=[{opacity:1,transform:'none'},{opacity:1,transform:'none'}];const a=node.animate(frames,{duration:options.duration,easing:options.easing||'cubic-bezier(.22,.76,.24,1)',fill:'both',...options, ...(reduce()?{duration:1,delay:0}: {})});sceneAnimations.push(a);a.finished.then(()=>{a.cancel();sceneAnimations=sceneAnimations.filter(x=>x!==a);}).catch(()=>{});return a;}
function render(entrance=true){if(state.view==='gallery'){spatialModel.invalidate();state.gestureTarget=-1;if(state.gesture==='target')state.gesture='off';}cancelScene();cancelPanel(false);document.documentElement.lang=state.locale==='zh'?'zh-Hant':'en';app.className=[state.locale==='zh'?'zh':'',protectedState()?'protected':'',$('#reduced').checked?'reduced':'',$('#opaque').checked?'opaque':'',$('#hitboxes').checked?'hitbox':'',state.view==='portrait'?(state.phase==='playing'?'playing':'preparing'):''].join(' ');app.style.setProperty('--accent',state.view==='gallery'&&state.target>=0?performers[state.target].accent:P().accent);const content=state.view==='gallery'?gallery():['focus','activation','portrait','release'].includes(state.view)?chapter():['home','attract','closing','souvenir'].includes(state.view)?standard(state.view):['privacy','tutorial','calibration'].includes(state.view)?reading(state.view):state.view==='chooser'?chooser():state.view==='postvideo'?postvideo():components();app.innerHTML=`<div class="view" data-view="${state.view}">${content}</div>${shell()}`;$('#family').value=state.view;app.dataset.view=state.view;app.dataset.phase=state.phase;if(entrance){if(state.view==='gallery'){app.querySelectorAll('.art-window').forEach((n,i)=>animateNode(n,[{opacity:.4,transform:'translateY(18px)'},{opacity:1,transform:'none'}],{duration:520,delay:i*20}));animateNode($('.identification'),[{opacity:.6},{opacity:1}],{duration:360});}else animateNode($('.view'),[{opacity:.45,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:300});}if(state.minimized&&!protectedState())showMinimized();paintSpatial();}
function navigate(view){const previous=state.view;if(view==='gallery'&&previous!=='gallery')spatialModel.gallery(false);panelReturn=null;state.overlay=null;state.minimized=null;state.error=false;state.view=view;if(view==='portrait')state.phase='prepare';render();if(view==='gallery'&&['focus','release','postvideo','closing'].includes(previous)){app.querySelector(`[data-performer="${state.performer}"]`)?.focus({preventScroll:true});return;}const first=app.querySelector('h1');if(first){first.tabIndex=-1;first.focus({preventScroll:true});}}
function setTarget(i,semantic=false,source='pointer'){spatialTarget(i,semantic?'gesture':source,true);}
function updateTracking(){const el=$('.tracking');if(el){el.dataset.status=state.gesture;el.textContent=trackingCopy();}}
function confirm(i,source){
 if(i<0||state.view!=='gallery'||state.overlay||document.querySelector('.overlay-plane'))return;
 const semantic=source.includes('fist')?'gesture':'explicit';
 const result=spatialModel.confirm(i,semantic);if(!result.accepted){log('Confirmation ignored: acquire a fresh stable target.','未接受確認：請重新取得穩定目標。');return;}
 stopSpatialSequence();paintSpatial();const sourceSurface=app.querySelector('.view:not(.gallery-ghost) .presence[data-performer="'+i+'"] .spatial-surface');
 const old=sourceSurface?.getBoundingClientRect(),oldView=app.querySelector('.view'),oldLight=oldView?.querySelector('.environment-light'),lightColor=oldLight?getComputedStyle(oldLight).backgroundColor:null,ghost=reduce()?null:oldView?.cloneNode(true);
 if(ghost){const originals=[...oldView.querySelectorAll('.art-window,.spatial-surface,.portrait')];ghost.querySelectorAll('.art-window,.spatial-surface,.portrait').forEach((n,index)=>{const current=getComputedStyle(originals[index]);n.style.transform=current.transform;n.style.opacity=current.opacity;n.style.filter=current.filter;n.style.transition='none';n.style.animation='none';});ghost.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));ghost.classList.add('gallery-ghost');ghost.inert=true;ghost.setAttribute('aria-hidden','true');}
 state.performer=i;state.target=i;state.gestureTarget=-1;state.gesture='off';navigate('focus');paintSpatial();
 const dest=app.querySelector('.chapter-art'),to=dest?.getBoundingClientRect();
 if(!reduce()&&old&&to&&ghost){app.append(ghost);const ghostLight=ghost.querySelector('.environment-light');if(ghostLight&&lightColor){ghostLight.style.backgroundColor=lightColor;const lightTween=ghostLight.animate([{backgroundColor:lightColor},{backgroundColor:LivingGlassSpatial.palettes[i].atmosphere}],{duration:280,fill:'forwards'});sceneAnimations.push(lightTween);lightTween.finished.catch(()=>{});}const ga=ghost.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.996)'}],{duration:650,easing:'cubic-bezier(.22,.76,.24,1)',fill:'forwards'});sceneAnimations.push(ga);ga.finished.catch(()=>{}).finally(()=>ghost.remove());
 const proxy=dest.cloneNode();proxy.alt='';proxy.className='spatial-transition-art';Object.assign(proxy.style,{position:'fixed',left:old.left+'px',top:old.top+'px',width:old.width+'px',height:old.height+'px',objectFit:'cover',objectPosition:i===0?'100% 32%':'50% 32%',pointerEvents:'none',borderRadius:'4px'});
 document.body.append(proxy);const a=proxy.animate([{left:old.left+'px',top:old.top+'px',width:old.width+'px',height:old.height+'px',opacity:1,objectPosition:i===0?'100% 32%':'50% 32%'},{left:to.left+'px',top:to.top+'px',width:to.width+'px',height:to.height+'px',opacity:0,objectPosition:'50% 35%'}],{duration:650,easing:'cubic-bezier(.22,.76,.24,1)',fill:'forwards'});sceneAnimations.push(a);a.finished.catch(()=>{}).finally(()=>proxy.remove());}
 log(performers[i].name+' confirmed. Theme and artwork bridge continuously into Focus.',performers[i].name+' 已確認，氛圍與作品連續過渡至凝視。');
}
function row(en,zh,descEn,descZh,action='deferred',labelEn='Unavailable',labelZh='目前無法使用',disabled=true){return `<div class="setting-row"><div><h3>${T(en,zh)}</h3><p>${T(descEn,descZh)}</p></div>${button(action,labelEn,labelZh,'secondary',disabled)}</div>`;}
function assistantBody(){return `<p class="panel-intro">${performers[state.assistant??state.performer].name} / ${T('A conversation, at your pace. Camera not required.','以你的步調對話，無須使用相機。')}</p><div class="suggestions">${['Meet this presence','About the exhibition','How to interact'].map((n,i)=>`<button disabled>${T(n,['認識此種存在','關於展演','如何互動'][i])}</button>`).join('')}</div><div class="empty-conversation"><p>${T('What would you like to explore?','你想探索什麼？')}</p><p class="fine">${T('Layout specimen. No assistant is connected and no response is fabricated.','版面示例，未連線至助理，亦未捏造回覆。')}</p></div><div class="input-specimen"><input disabled placeholder="${T('Ask a question…','提出問題…')}" aria-label="${T('Question unavailable in design preview','設計預覽不提供問題輸入')}"><button disabled>${T('Ask','詢問')}</button></div>`;}
function panelContent(type){if(type==='settings')return `<p class="panel-intro">${T('Quiet controls. Return to exactly where you were.','安靜調整，回到剛才的體驗。')}</p>${row('Language','語言','English / Traditional Chinese','English／繁體中文','locale','Switch','切換',false)}${row('Sound','聲音','Volume, mute and output · functionality deferred','音量、靜音與輸出・功能暫緩實作')}${row('Accessibility','無障礙','Motion, effects and text · functionality deferred','動態、視覺效果與文字・功能暫緩實作')}${row('Camera & privacy','相機與隱私','Camera off in this preview; permission and preview remain separate','此預覽未啟動相機，權限與預覽分開處理','privacy','Review','檢視',false)}${row('End / restart','結束／重新開始','Reset scope and destination require approval','重設範圍與目的地仍待核准')}<p class="fine">${T('The controls above do not apply deferred settings. Use the external review toolbar to compare motion and effects.','上述控制項不會套用暫緩實作的設定。可使用外部檢視工具列比較動態與視覺效果。')}</p>`;if(type==='ai')return assistantBody();if(type==='help')return `<p class="panel-intro">${T('Point, then make a fist to confirm. Both open palms begin the portrait; a held open palm requests Back where supported.','指向後握拳確認。張開雙手可開始流動畫像；於支援處張開單手並保持，可請求返回。')}</p><p class="panel-intro">${T('Pointer, Tab, Enter/Space and 1–6 remain alternatives. Gesture targeting never moves a hit region.','也可使用滑鼠、Tab、Enter／Space 與 1–6。手勢指向不會移動互動區域。')}</p><div class="actions">${button('tutorial','Review guide','檢視操作說明','secondary')}${button('calibration','Optional alignment','選用對位協助','quiet')}</div>`;if(type==='privacy')return `<span class="status-tag">${T('Camera off','相機已關閉')}</span><p class="panel-intro">${T('Capture consent, temporary suspension, readiness and preview visibility are separate. This prototype does not request or grant camera permission.','擷取同意、暫停擷取、就緒狀態與預覽是否顯示皆分開處理。此原型不會要求或授予相機權限。')}</p><p class="panel-intro">${T('In production, revocation must immediately stop capture through the existing owner; it must not wait for an animation.','正式產品中，撤回同意必須立即透過既有擷取擁有者停止擷取，不可等待動畫完成。')}</p>${button('stop-camera','Camera already off','相機已關閉','secondary',true)}`;if(type==='safe-exit')return `<p class="panel-intro">${T('Existing portrait cancellation is preserved. Immediate exit during Activation is still a policy requiring approval. This preview can return safely without operating media.','保留既有流動畫像取消行為。啟動階段的立即離開政策仍待核准。此預覽可安全返回，不會操作媒體。')}</p><div class="actions">${button('cancel','Preview cancellation','預覽取消')}${button('close','Keep this moment','繼續此刻','secondary')}</div>`;return '';}
const panelTitle=t=>({settings:T('Your experience','你的體驗'),ai:T('A different perspective','換個角度，延續感知'),help:T('A little guidance','從容探索的提示'),privacy:T('Your camera, your choice','你的相機，由你選擇'),'safe-exit':T('Leave this moment?','要離開此刻嗎？')}[t]);
function cancelPanel(remove=true){panelGeneration++;if(panelAnimation){panelAnimation.cancel();panelAnimation=null;}if(remove)app.querySelector('.overlay-plane')?.remove();app.querySelectorAll('.view,.dock').forEach(n=>n.inert=false);state.overlay=null;spatialModel.resume();app.querySelectorAll('.portrait').forEach(n=>n.style.animationPlayState=document.hidden?'paused':'running');}
function tweenPanel(opening,onFinish){const panel=$('.panel');if(!panel)return;const current=getComputedStyle(panel),from={transform:current.transform==='none'?'translateY(0) scale(1)':current.transform,opacity:current.opacity};if(panelAnimation)panelAnimation.cancel();const g=++panelGeneration;const end={transform:reduce()?'none':opening?'translateY(0) scale(1)':'translateY(65px) scale(.94)',opacity:opening?1:0};const frames=reduce()?[{transform:'none',opacity:opening?1:from.opacity},end]:[from,end];panelAnimation=panel.animate(frames,{duration:reduce()?1:opening?360:220,easing:opening?'cubic-bezier(.18,.82,.22,1)':'cubic-bezier(.4,0,.8,.25)',fill:'forwards'});panelAnimation.finished.then(()=>{if(g!==panelGeneration)return;panel.style.transform=end.transform;panel.style.opacity=String(end.opacity);panelAnimation.cancel();panelAnimation=null;onFinish?.();}).catch(()=>{});}
function openPanel(type,fromButton){if(protectedState()&&!['privacy','safe-exit'].includes(type)){log('Deferred until a stable boundary; no automatic opening later.','待穩定階段再開啟，不會自動彈出。');return;}if(state.view==='gallery')settleSpatialEntrance();else cancelScene();spatialModel.suspend();paintSpatial();const existing=$('.panel');if(existing?.dataset.kind===type){state.overlay=type;tweenPanel(true);existing.querySelector('[data-action="close"]').focus({preventScroll:true});return;}if(type==='privacy'&&state.overlay==='settings')panelReturn={type:'settings',action:'privacy',opener};else if(!panelReturn||type!=='privacy')panelReturn=null;state.gestureTarget=-1;if(state.gesture==='target')state.gesture='off';updateTracking();cancelPanel();spatialModel.suspend();opener=fromButton||document.getElementById('shell-'+type)||document.activeElement;state.overlay=type;state.minimized=null;$('.minimized')?.remove();const plane=document.createElement('div');plane.className='overlay-plane';plane.innerHTML=`<section class="panel" data-kind="${type}" role="dialog" aria-modal="true" aria-labelledby="panel-title" style="transform:translateY(65px) scale(.94);opacity:0"><header><h2 id="panel-title">${panelTitle(type)}</h2><div class="panel-tools">${['settings','ai'].includes(type)?`<button data-action="minimize" aria-label="${T('Minimize panel','縮小面板')}">${T('Minimize','縮小')}</button>`:''}<button data-action="close" aria-label="${T('Close panel','關閉面板')}">${T('Close','關閉')}</button></div></header>${panelContent(type)}</section>`;app.append(plane);const context=document.createElement('span');context.className='panel-context';context.setAttribute('aria-hidden','true');plane.querySelector('.panel').append(context);paintSpatial();app.querySelectorAll('.portrait').forEach(n=>n.style.animationPlayState='paused');app.querySelectorAll('.view,.dock').forEach(n=>n.inert=true);document.getElementById('shell-'+type)?.setAttribute('aria-expanded','true');plane.querySelector('[data-action="close"]').focus({preventScroll:true});tweenPanel(true);}
function closePanel(minimize=false){if(!$('.panel'))return;const closingType=state.overlay||$('.panel').dataset.kind,restore=opener,returnTo=panelReturn;state.overlay=null;tweenPanel(false,()=>{app.querySelector('.overlay-plane')?.remove();spatialModel.resume();paintSpatial();app.querySelectorAll('.view,.dock').forEach(n=>n.inert=false);app.querySelectorAll('.portrait').forEach(n=>n.style.animationPlayState=document.hidden?'paused':'running');document.getElementById('shell-'+closingType)?.setAttribute('aria-expanded','false');if(returnTo&&!minimize){panelReturn=null;openPanel(returnTo.type,returnTo.opener);app.querySelector(`.panel [data-action="${returnTo.action}"]`)?.focus({preventScroll:true});return;}if(minimize){state.minimized=closingType;showMinimized();$('.minimized')?.focus({preventScroll:true});}else if(restore?.isConnected)restore.focus({preventScroll:true});else app.querySelector('.dock button')?.focus({preventScroll:true});});}
function showMinimized(){if($('.minimized'))return;const chip=document.createElement('button');chip.className='minimized';chip.dataset.action='restore';chip.textContent=T('Resume ','繼續開啟')+panelTitle(state.minimized);app.append(chip);}
function changeLocale(){const overlay=state.overlay,focusAction=document.activeElement?.dataset.action;state.locale=state.locale==='en'?'zh':'en';$('#locale').value=state.locale;render(false);if(overlay){openPanel(overlay);if(focusAction)app.querySelector(`.panel [data-action="${focusAction}"]`)?.focus({preventScroll:true});}}
function action(a,source){if(['settings','ai','help','privacy','safe-exit'].includes(a))return openPanel(a,source);if(a==='close')return closePanel();if(a==='minimize')return closePanel(true);if(a==='restore')return openPanel(state.minimized,source);if(a==='locale')return changeLocale();if(a==='confirm')return confirm(state.target,'explicit action');if(a==='activate'){state.view='activation';render();return;}if(a==='cancel'){state.phase='prepare';navigate('release');log('Cancellation illustrated. No media completion event was generated.','已呈現取消動態，未產生媒體完成事件。');return;}if(a==='privacy-page')return navigate('privacy');if(a==='tutorial-next'){if(state.tutorial<2){state.tutorial++;render();}else navigate('gallery');return;}if(families.some(([id])=>id===a))navigate(a);}
// Spatial pointer ownership and pose are registered by setupSpatialReview().
// Keyboard focus remains separate from gesture acquisition.
app.addEventListener('click',e=>{const b=e.target.closest('[data-performer]');if(b&&!state.overlay&&!$('.overlay-plane'))return confirm(+b.dataset.performer,'pointer/keyboard activation');const context=e.target.closest('[data-assistant]');if(context){state.assistant=+context.dataset.assistant;return openPanel('ai',context);}const control=e.target.closest('[data-action]');if(control)action(control.dataset.action,control);});
document.addEventListener('keydown',e=>{const dialog=$('.panel');if(dialog){if(e.key==='Escape'){e.preventDefault();closePanel();return;}if(e.key==='Tab'){const ns=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),[tabindex="0"]')];if(!ns.length)return;const first=ns[0],last=ns[ns.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.target.matches('input,select,textarea'))return;if(state.view==='gallery'&&/^[1-6]$/.test(e.key)){e.preventDefault();confirm(+e.key-1,'numeric key');return;}if(e.key==='Escape'&&['focus','release','postvideo'].includes(state.view)){e.preventDefault();navigate('gallery');}});
for(const id of ['treatment','family','locale','reduced','opaque','hitboxes'])$('#'+id).addEventListener('change',()=>{
 if(['treatment','reduced','opaque','hitboxes'].includes(id)){paintSpatial();return;}
 stopSpatialSequence();reviewTimers.forEach(clearTimeout);reviewTimers=[];state.layout='arc';
 state.locale=$('#locale').value;const v=$('#family').value;state.minimized=null;
 if(['settings','ai'].includes(v)){state.view='gallery';spatialModel.invalidate();render(false);openPanel(v);$('#family').value=v;}
 else{if(v==='gallery'&&state.view!=='gallery')spatialModel.gallery(false);state.view=v;if(v==='portrait')state.phase='prepare';render(id==='family');}
});
$('.event-actions').addEventListener('click',e=>{const ev=e.target.closest('[data-event]')?.dataset.event;if(!ev)return;if(handleSpatialReviewEvent(ev))return;reviewTimers.forEach(clearTimeout);reviewTimers=[];if(ev==='entrance')render();if(['ready','point','loss','recover'].includes(ev)){if(state.view!=='gallery')navigate('gallery');if(ev==='point'){setTarget(state.target<0?0:state.target,true);}else{state.gesture={ready:'ready',loss:'lost',recover:'recovered'}[ev];state.gestureTarget=-1;updateTracking();}}if(ev==='fist'){if(state.view==='gallery'&&state.gesture==='target'&&state.gestureTarget>=0)confirm(state.gestureTarget,'review fist event');else return log('Fist ignored: acquire a fresh gesture target first.','未接受握拳：請先重新取得手勢目標。');}if(ev==='activate'){state.view='activation';render();}if(ev==='prepare'){state.view='portrait';state.phase='prepare';render();}if(ev==='frame'){if(state.view!=='portrait')return log('First-frame specimen requires preparation first.','請先進入準備狀態，再檢視第一影格。');state.phase='playing';render();}if(ev==='complete'){if(state.view!=='portrait'||state.phase!=='playing')return log('Completion ignored: first-frame specimen must be shown first.','未接受完成事件：須先顯示第一影格示例。');navigate('release');}if(ev==='cancel')action('cancel');if(ev==='error'){state.view='components';render();}if(ev==='interrupt'){if(protectedState())navigate('gallery');openPanel('settings');reviewTimers.push(setTimeout(()=>closePanel(),90),setTimeout(()=>openPanel('settings'),170));}log(`Review event: ${ev}. No detector, media callback or deferred business outcome executed.`,`檢視事件：${ev}。未執行偵測器、媒體回呼或暫緩實作的功能結果。`);});
document.addEventListener('visibilitychange',()=>{app.querySelectorAll('.portrait').forEach(n=>n.style.animationPlayState=document.hidden||$('.panel')?'paused':'running');paintSpatial();});
setupSpatialReview();
render();
